def tr(language: str, key: str, **values) -> str:
    language = language if language in TEXT else "en"
    return TEXT[language][key].format(**values)


def status_text(language: str, value: str | None) -> str:
    language = language if language in STATUS else "en"
    key = (value or "UNKNOWN").upper()
    return STATUS[language].get(key, key)
